import { z } from "zod";
import { INCIDENT_PERSON_ROLES, INCIDENT_STATUSES, INCIDENT_TYPES } from "./domain.ts";

const optionalText = (max: number) =>
  z
    .string()
    .trim()
    .max(max)
    .nullish()
    .transform((v) => (v ? v : null));
const instant = z.iso.datetime({ offset: true }).transform((v) => new Date(v));

export const incidentPersonSchema = z.object({
  personId: z.uuid(),
  role: z.enum(INCIDENT_PERSON_ROLES).default("involved"),
});

/**
 * Body of POST /api/incidents. `clientKey` is generated by the app when a draft is written
 * (possibly offline) and makes the replay idempotent: the same key from the same user returns
 * the incident already created.
 */
export const createIncidentSchema = z.object({
  type: z.enum(INCIDENT_TYPES),
  occurredAt: instant,
  place: optionalText(200),
  teamId: z
    .uuid()
    .nullish()
    .transform((v) => v ?? null),
  description: z.string().trim().min(1).max(4000),
  people: z.array(incidentPersonSchema).max(30).default([]),
  clientKey: z.uuid().nullish(),
});
export type CreateIncidentInput = z.infer<typeof createIncidentSchema>;

/**
 * Body of PATCH /api/incidents/:id. The reporter may correct the report while it is open;
 * `status` and `followUp` need `incidents.manage`.
 */
export const updateIncidentSchema = z
  .object({
    type: z.enum(INCIDENT_TYPES),
    occurredAt: instant,
    place: optionalText(200),
    description: z.string().trim().min(1).max(4000),
    status: z.enum(INCIDENT_STATUSES),
    followUp: optionalText(4000),
  })
  .partial();
export type UpdateIncidentInput = z.infer<typeof updateIncidentSchema>;

export const listIncidentsQuerySchema = z.object({
  type: z.enum(INCIDENT_TYPES).optional(),
  status: z.enum(INCIDENT_STATUSES).optional(),
  teamId: z.uuid().optional(),
});
export type ListIncidentsQuery = z.infer<typeof listIncidentsQuerySchema>;
